BEGIN;
SET LOCAL search_path=pg_catalog,public;
CREATE TABLE public.admin_users (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 username VARCHAR(100) NOT NULL,
 display_name VARCHAR(150) NOT NULL,
 password_hash TEXT NOT NULL,
 is_active BOOLEAN NOT NULL DEFAULT TRUE,
 created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 -- Provenance makes the two-database migration rerunnable without ID guessing.
 legacy_source_id UUID,
 legacy_user_id BIGINT,
 migration_pending BOOLEAN NOT NULL DEFAULT FALSE,
 CONSTRAINT admin_users_legacy_source_unique UNIQUE(legacy_source_id,legacy_user_id),
 CONSTRAINT admin_users_legacy_source_pair CHECK ((legacy_source_id IS NULL)=(legacy_user_id IS NULL))
);
CREATE UNIQUE INDEX admin_users_username_lower_key ON public.admin_users(lower(username));
CREATE TABLE public.admin_sessions (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
 admin_id BIGINT NOT NULL REFERENCES public.admin_users(id),
 created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 last_seen_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 idle_expires_at TIMESTAMPTZ NOT NULL,
 absolute_expires_at TIMESTAMPTZ NOT NULL,
 revoked_at TIMESTAMPTZ
);
CREATE INDEX admin_sessions_admin_id_idx ON public.admin_sessions(admin_id);
CREATE TABLE public.admin_session_tokens (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 session_id UUID NOT NULL REFERENCES public.admin_sessions(id),
 token_hash BYTEA NOT NULL UNIQUE,
 issued_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 replaced_at TIMESTAMPTZ,
 grace_expires_at TIMESTAMPTZ
);
CREATE INDEX admin_session_tokens_session_id_idx ON public.admin_session_tokens(session_id);
CREATE UNIQUE INDEX admin_session_tokens_current_per_session_key ON public.admin_session_tokens(session_id) WHERE replaced_at IS NULL;

CREATE TABLE public.users (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username            VARCHAR(100) NOT NULL,
    display_name        VARCHAR(150) NOT NULL,
    password_hash       TEXT NOT NULL,
    is_active           BOOLEAN NOT NULL DEFAULT TRUE,
    auth_version BIGINT NOT NULL DEFAULT 1 CHECK(auth_version>0),
 rotation_version BIGINT NOT NULL DEFAULT 1 CHECK(rotation_version>0),
    created_by_admin_id BIGINT,
    legacy_created_by_user_id BIGINT,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX users_username_lower_key ON public.users (lower(username));

CREATE TABLE public.access_groups (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name            VARCHAR(100) NOT NULL UNIQUE,
    leader_user_id  BIGINT REFERENCES public.users(id),
    description     TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE public.user_groups (
    user_id     BIGINT NOT NULL REFERENCES public.users(id),
    group_id    BIGINT NOT NULL REFERENCES public.access_groups(id),
    joined_at   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (user_id, group_id)
);

CREATE INDEX user_groups_group_id_idx ON public.user_groups (group_id);

ALTER TABLE public.access_groups ADD CONSTRAINT access_groups_leader_membership
 FOREIGN KEY(leader_user_id,id) REFERENCES public.user_groups(user_id,group_id)
 DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE public.managed_databases (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    display_name         VARCHAR(150) NOT NULL UNIQUE,
    dbms_type            VARCHAR(30) NOT NULL DEFAULT 'postgresql',
    host                 TEXT NOT NULL,
    port                 INTEGER NOT NULL DEFAULT 5432,
    database_name        TEXT NOT NULL,
    db_username          TEXT NOT NULL,
    encrypted_password   BYTEA NOT NULL,
    connection_options   JSONB DEFAULT '{}'::JSONB,
    is_active            BOOLEAN NOT NULL DEFAULT TRUE,
    created_by_admin_id  BIGINT,
    legacy_created_by_user_id BIGINT,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT managed_databases_port_check CHECK (port BETWEEN 1 AND 65535),
    CONSTRAINT managed_databases_connection_options_check
        CHECK (connection_options IS NULL OR jsonb_typeof(connection_options) = 'object')
);

CREATE TABLE public.group_database_permissions (
    group_id        BIGINT NOT NULL REFERENCES public.access_groups(id),
    database_id     BIGINT NOT NULL REFERENCES public.managed_databases(id),
    access_level    VARCHAR(20) NOT NULL,
    granted_by_admin_id BIGINT,
    legacy_granted_by_user_id BIGINT,
    granted_at      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (group_id, database_id),
    CONSTRAINT group_database_permissions_access_level_check
        CHECK (access_level IN ('view_only', 'view_edit'))
);

CREATE INDEX group_database_permissions_database_id_idx
    ON public.group_database_permissions (database_id);


CREATE TABLE public.migration_authority_clock (
 singleton BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK(singleton),
 revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0)
);
INSERT INTO public.migration_authority_clock(singleton) VALUES(TRUE);
CREATE FUNCTION public.advance_migration_authority() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 UPDATE public.migration_authority_clock SET revision=revision+1 WHERE singleton;
 RETURN NULL;
END $$;
CREATE TRIGGER migration_authority_groups AFTER INSERT OR UPDATE OR DELETE ON public.access_groups
 FOR EACH STATEMENT EXECUTE FUNCTION public.advance_migration_authority();
CREATE TRIGGER migration_authority_memberships AFTER INSERT OR UPDATE OR DELETE ON public.user_groups
 FOR EACH STATEMENT EXECUTE FUNCTION public.advance_migration_authority();
CREATE TRIGGER migration_authority_grants AFTER INSERT OR UPDATE OR DELETE ON public.group_database_permissions
 FOR EACH STATEMENT EXECUTE FUNCTION public.advance_migration_authority();
CREATE TRIGGER migration_authority_users AFTER INSERT OR UPDATE OR DELETE ON public.users
 FOR EACH STATEMENT EXECUTE FUNCTION public.advance_migration_authority();
CREATE TRIGGER migration_authority_databases AFTER INSERT OR UPDATE OR DELETE ON public.managed_databases
 FOR EACH STATEMENT EXECUTE FUNCTION public.advance_migration_authority();
CREATE FUNCTION public.check_group_leaders() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF EXISTS (SELECT 1 FROM public.access_groups g JOIN public.users u ON u.id=g.leader_user_id
            WHERE NOT u.is_active) THEN
  RAISE EXCEPTION 'replace the group leader before deactivating the user' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER active_group_leaders AFTER UPDATE ON public.users
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_group_leaders();
CREATE CONSTRAINT TRIGGER valid_group_leaders AFTER INSERT OR UPDATE ON public.access_groups
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_group_leaders();
CREATE FUNCTION public.prevent_leader_removal() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.leader_user_id IS NOT NULL AND NEW.leader_user_id IS NULL THEN
  RAISE EXCEPTION 'replace the designated leader instead of clearing it' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER preserve_group_leader BEFORE UPDATE ON public.access_groups
 FOR EACH ROW EXECUTE FUNCTION public.prevent_leader_removal();
COMMIT;
